custom_css:
/* 本主题免费公开发布于dc旅程社区，禁二改二传，商用引流/倒卖的sm */

/* ===== 0. 变量定义 ===== */
:root {
  --圆角: 5px;
  --圆角-中: 15px;
  --阴影: rgba(0, 0, 0, 0.1);
  --主题色: rgba(255, 192, 203, 0.4);
  --主题色-2: rgba(255, 192, 203);
  --辅助色: #feceda;
  --辅助色-2: #ffdeeb;
  --辅助色-3: #fff0f6;
  --渐变: linear-gradient(to right, var(--辅助色-3), var(--辅助色-2), var(--辅助色), #fcc2d7, var(--主题色-2));
}

/* ===== 1. 文本样式 ===== */
/* 选中文字高亮 */
::selection {
  background: color-mix(in srgb, var(--SmartThemeUnderlineColor) 50%, white);
  color: var(--SmartThemeQuoteColor);
}

/* 对话/引用 */
q {
    text-decoration: underline dashed Currentcolor 1px;
    text-underline-offset: 0.2em;
}

/* 斜体 */
em {
    color: #fff !important;
    background-color: var(--SmartThemeEmColor);
    background-clip: text;
    -webkit-text-stroke: 1px transparent;
    text-shadow: none !important;
    text-decoration: underline solid var(--SmartThemeEmColor) 0.5px;
    text-underline-offset: 0.2em;
}

/* 删除 */
del {
  font-style: italic;
  color: var(--SmartThemeQuoteColor);
  text-decoration-color: crimson;
}

/* 代码块 */
code {
    border-radius: 1px;
    background: transparent;
    border: 1.5px ridge var(--SmartThemeUnderlineColor);
    color: var(--SmartThemeUnderlineColor);
}

.mes pre code {
    border: 0;
    outline: 1.5px outset var(--SmartThemeUnderlineColor);
    background: var(--SmartThemeUnderlineColor);
}

/* md引用文本 */
blockquote {
    padding-left: 5px;
    background: linear-gradient(to right, transparent 5px, var(--SmartThemeUnderlineColor) 2px, transparent) !important;
}

/* ===== 2. 滚动条 & 滑动条 ===== */
/* --- 滚动条 --- */
#chat::-webkit-scrollbar {
    display: none;
}

::-webkit-scrollbar {
    width: 3.5px;
}

::-webkit-scrollbar-thumb {
    background: linear-gradient(to top, var(--辅助色-3), var(--辅助色-2), var(--辅助色), #fcc2d7, var(--主题色-2)) !important;
    border: none !important;
    box-shadow: none !important;
}

/* --- 滑动条 --- */
input[type="range"] {
    background: var(--渐变) !important;
    border-radius: 0 !important;
    height: 4px !important;
    filter: none !important;
    box-shadow: none !important;
}

#left-nav-panel input[type="range"] {
  box-shadow: 1px 1px 1px var(--阴影) !important;
}

input[type="range"]::-webkit-slider-thumb {
  transform: scale(0.85);
  -webkit-transform: scale(0.85);
  background: var(--渐变) !important;
  border: 2px solid var(--SmartThemeBorderColor);
  outline: 2.5px solid var(--主题色);
  filter: none !important;
  box-shadow: none !important;
}

/* ===== 3. 聊天区域 ===== */
#chat {
  background: none;
  border: none;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* --- 欢迎页 --- */
.welcomePanel .recentChatList .recentChat {
  margin-bottom: 10px;
  border: none;
  border-bottom: 2px solid var(--辅助色);
  border-radius: var(--圆角);
  background: linear-gradient(to right, var(--辅助色-2), transparent),
    #fff;
  box-shadow: 1px 1.5px 3px var(--阴影);
}

/* 欢迎页按钮 */
.mes_button.showRecentChats .fa-circle-chevron-down::before {
  content: "\f07c";
  color: var(--SmartThemeEmColor);
}

.mes_button.hideRecentChats .fa-circle-xmark::before {
  content: "\f07b";
  color: var(--SmartThemeEmColor);
}

/* --- 最后一条消息 --- */
.last_mes {
  margin-bottom: 80px !important;
}

.last_mes .mesAvatarWrapper {
  padding: 0 !important;
}

.last_mes .mes_block {
    transform: none !important;
}

/* ----- 消息气泡 ----- */
#chat .mes {
  flex-direction: column;
  margin: 55px auto 20px;
  padding: 35px 3px 5px;
  width: 96%; /* 宽度 */
  background-image: 
    linear-gradient(45deg, 
      var(--主题色) 25%, 
      transparent 25%, 
      transparent 50%, 
      var(--主题色) 50%, 
      var(--主题色) 75%, 
      transparent 75%, 
      transparent),
    linear-gradient(-45deg, 
      var(--主题色) 25%, 
      transparent 25%, 
      transparent 50%, 
      var(--主题色) 50%, 
      var(--主题色) 75%, 
      transparent 75%, 
      transparent);
  background-size: 15px 15px;
  background-color: #fff;
  box-shadow:
    0 0 2px var(--阴影),
    0 2px 4px var(--阴影);
}

/* --- 文本区域 --- */
.mes_block {
  display: flex;
  flex-direction: column;
  padding: 20px 8px 50px;
  background: #fff;
  box-shadow:
    inset 0 0 1px 1px var(--主题色),
    inset 0 0 1px 1px var(--主题色);
}

/* User单独设置布局 */
.mes[is_user="true"] .mes_block {
  align-items: center;
}

/* --- 文本框 --- */
.mes_text {
  text-align: justify;
  padding: 0;
}

.mes[is_user="true"] p:last-child {
  margin-bottom: 0;
}

/* --- 左右箭头 --- */
.swipe_right,
.swipe_left {
  color: var(--主题色);
}

.swipeRightBlock {
  margin-right: 10px;
}

/* --- 小铅笔 --- */
.mes_button,
.mes_edit_buttons {
  font-size: var(--mainFontSize);
  text-shadow: 0 0 2px var(--主题色) !important;
  filter: none !important;
  padding: 3px 2px 5px;
  opacity: 1;
}

/* 子按钮 */
.mes .menu_button {
  opacity: 1;
  border-radius: 50%;
  box-shadow: 1px 1px 0.5px var(--SmartThemeBorderColor);
}

.mes .mes_edit_delete {
  background-color: red;
}

/* 替换图标 */
/* 📍Char 小铅笔 */
.mes[is_user="false"] .ch_name {
  order: 1;
}

.mes[is_user="false"] .mes_button.mes_edit.fa-solid.fa-pencil::before,
.mes[is_user="false"] .extraMesButtonsHint::before {
  background-color: var(--主题色);
  border-radius: 2px;
  border-bottom: 1px solid var(--主题色);
  box-shadow: 1px 1px 1px var(--阴影);
  margin: 2px auto;
  padding: 2px 8px;
}

.extraMesButtonsHint::before {
  content: "更多";
}

.mes .mes_button.mes_edit.fa-solid.fa-pencil::before {
  content: "编辑";
}

/* 📍用户小铅笔 */
.mes[is_user="true"] .extraMesButtonsHint::before {
  content: "°.✩┈꒰১";
}

.mes[is_user="true"] .mes_button.mes_edit.fa-solid.fa-pencil::before {
  content: "໒꒱┈✩.°";
}

/* ----- 名字区域 ----- */
/* --- 名字 --- */
.mes .name_text {
  position: absolute;
  top: -5px;  /* 上下 */
  left: 230px;
  transform-origin: left center;
  transform: translate(-50%, 50%) scale(1.5); /* 大小 */
  font-style: italic;
  &::after {
    content: "";
    position: absolute;
    z-index: -1;
    top: 0;
    left: 50%;
    transform: translateX(-50%);
    width: 150%;
    height: 100%;
    background-image: linear-gradient(to right, transparent 0%, var(--主题色) 20%, var(--主题色) 80%, transparent 100%);
    background-repeat: repeat-x;
    background-position: 0 65%;
    background-size: 100% 40%; 
    background-color: ransparent;
  }
}

/* --- 时间戳 --- */
.mes .timestamp{
  position: absolute;
  padding: 2px 5px;
  bottom: 25px;  /* 上下 */
  right: 50%;
  transform: translate(50%, 50%);
  font-size: calc(var(--mainFontSize) * 0.85);
  box-shadow: 0 1px 2px 1px var(--主题色);
}

/* ----- 思维链 ----- */
.mes_reasoning_header {
  background: color-mix(in srgb, var(--辅助色-2) 40%, transparent);
  border-radius: 2px;
  border-bottom: 1px solid var(--主题色);
  box-shadow: 1px 1px 1px var(--阴影);
  margin: 2px auto;
  padding: 2px 8px;
}

.mes_reasoning_arrow {
  display: none;
}

/* 📍思维链文字自定义 */
.mes_reasoning_header_title {
  font-size: 0;
  &::before {
    content: "-✦- 少 男 心 事 -✦-";
    font-size: calc(var(--mainFontSize) * 1.1);
    color: #ffffff;
    text-shadow:
      0 0 4px var(--主题色-2),
      0 0 2px var(--主题色-2),
      0 0 1px var(--主题色-2),
      0 0 1px var(--阴影);
  }
}

.mes_reasoning_details[open] .mes_reasoning_header_title::before {
  content: "-✦- 阅读结束 -✦-";
}

/* 思维链父容器 */
.mes_reasoning_details {
  position: relative;
  order: -1;
}

/* 打开状态时100%宽度 */
.mes_reasoning_details[open] {
  width: 100%;
}

.mes_reasoning_actions {
  position: absolute;
  right: 5px;
  top: 5px;
  z-index: 10;
  flex-shrink: 0;
  padding: 0 5px;
}

@media (max-width: 768px) {
  .mes_reasoning {
    width: 100%;
    max-height: 550px; /* 思维链内容高度 */
    overflow: hidden auto;
    font-size: calc(var(--mainFontSize) * 0.9);
    border: 2px dashed var(--SmartThemeBorderColor);
    background: color-mix(in srgb, var(--主题色) 20%, transparent);
  }
  .mes_reasoning_actions {
    right: 0;
    top: -5px;
  }
}

/* ----- 头像区域 ----- */
.mesAvatarWrapper {
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
  gap: 15px;
  margin-left: 180px; /* 📍调整楼层三元素位置*/
}

/* --- 📍头像 --- */
/* 全局头像 */
.avatar img,
body.big-avatar .avatar img{
    box-shadow: none;
    border: none;
}

/* 消息框内头像 */
.mes .avatar {
  position: absolute;
  transform: scale(2.15); /* 大小 */
  left: -110px; /* 左右 */
  top: -50px; /* 上下 */
}

.mes[is_user="true"] .mesAvatarWrapper {
  margin-left: 210px; /* 📍调整楼层三元素位置*/
}

.mes[is_user="true"] .avatar {
  left: -140px; /* 左右 */
}

.mes .avatar::before {
    content: "";
    position: absolute;
    left: 50%;
    top: 50%;
    width: 107%;
    height: auto;
    aspect-ratio: 512/538;
    transform: translate(-50%, -50%);
    background: var(--渐变);
    mask: url(https://files.catbox.moe/ief6w8.png) center/contain no-repeat;
    -webkit-mask: url(https://files.catbox.moe/ief6w8.png) center/contain no-repeat;
}

.mes .avatar img {
  -webkit-mask-image: url('https://files.catbox.moe/12wmbv.png');
  mask-image: url('https://files.catbox.moe/12wmbv.png');
  -webkit-mask-size: contain;
  mask-size: contain;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  -webkit-mask-position: center;
  mask-position: center;
  pointer-events: auto;
}

/* --- 楼层、计时器、Tokens --- */
.mesIDDisplay:empty,
.mes_timer:empty,
.tokenCounterDisplay:empty {
  display: none !important;
}

.mes .mesIDDisplay,
.mes .mes_timer,
.mes .tokenCounterDisplay {
  position: relative;
  top: -50%;
  padding: 0 6px;
  font-style: italic;
  color: var(--主题色-2);
  &::after {
    content: "";
    position: absolute;
    left: 0;
    width: 100%;
    height: 100%;
    background: var(--SmartThemeBodyColor);
    z-index: -1;
    transform: skew(-30deg);
    box-shadow: 5px 3px 0px 0px var(--主题色-2);
  }
}

/* ===== 4. 菜单抽屉 ===== */
/* --- 抽屉页背景 --- */
.drawer-content {
  box-shadow: none !important;
  border-radius: 0 0 var(--圆角-中) var(--圆角-中);
  border: none;
  border-bottom: 1.5px solid var(--SmartThemeBorderColor);
}

/* 预设页 & 角色管理页 */
#left-nav-panel,
#right-nav-panel {
  border-bottom: 1.5px solid var(--描边);
}

/* 部分菜单页全屏 by NAKARI */
.drawer-content.openDrawer {
    max-height: calc(100dvh - var(--topBarBlockSize));
}

#left-nav-panel,
#right-nav-panel {
    height: 100dvh;
    max-height: 100dvh;
}

@media (max-width: 600px) {
  #left-nav-panel,
  #right-nav-panel {
    max-height: calc(100dvh - var(--topBarBlockSize));
    padding-right: 0;
  }
}

/* --- 标题栏 --- */
.standoutHeader,
.inline-drawer-header,
#theme-manager-header,
#extensions_settings .inline-drawer-toggle.inline-drawer-header, 
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4:not(#theme-manager-header h4),
#top-settings-holder h4:not(#ai-config-button):not(#rightNavHolder):not(#theme-manager-header h4) {
  background: var(--辅助色-3) !important;
  filter: none !important;
  border: none;
  border-radius: var(--圆角);
  box-shadow:
    1px 1px 2px var(--阴影),
    inset 0 0 0 1px var(--SmartThemeBorderColor);
  margin-bottom: 5px;
  padding: 3px 5px;
}

/* 箭头 */
.inline-drawer-icon {
  font-size: calc(var(--mainFontSize) * 1.2);
  color: var(--主题色-2);
  filter: none !important;
  opacity: 1;
}

/* 闭合状态 */
.inline-drawer-icon::before {
    content: "✿" !important;
}

/* 展开状态 */
.inline-drawer-icon.up::before {
    content: "❀" !important;
    font-size: calc(var(--mainFontSize) * 1.35);
}

/* --- 按钮 --- */
.menu_button:not(.mes_edit_buttons *) {
  color: var(--辅助色);
  background: transparent;
  box-shadow: 1px 1px 2px var(--阴影);
  filter: none !important;
}

/* 警告按钮 */
#ddelete_button,
#dialogue_del_mes_ok,
#dialogue_popup_ok,
#bulk_tag_popup_reset,
#bulk_tag_popup_remove_mutual,
.mes_edit_cancel.menu_button,
.menu_button.popup-button-ok,
.redWarningBG {
  background: crimson !important;
  color: black !important;
}

/* --- 勾选框 --- */
input[type="checkbox"] {
    background: var(--主题色);
    border: none;
    border-radius: 20%;
    box-shadow: 1px 1px 2px var(--阴影);
    outline: none;
}

.checkbox_label {
  display: flex;
  align-items: center;
}

input[type="checkbox"]:checked {
  background: var(--主题色-2);
  border: none;
  outline: none;
}

/* --- 下拉框 --- */
#character_sort_order,
select.text_pole,
select {
  background-color: var(--SmartThemeBlurTintColor);
  outline: none !important;
  box-shadow: 1px 1px 2px var(--阴影);
  margin-bottom: 2px !important;
}

/* --- 输入框 --- */
/* 搜索框 + 部分输入框 */
#settingsSearch.textarea_compact,
.text_pole:not(.objective-task):not(select) {
  background-color: var(--SmartThemeBlurTintColor);
  outline: none !important;
  box-shadow: 1px 1px 2px var(--阴影);
}

input[type="text"],
input[type="number"],
input[type="switch"],
input:not([type]),
textarea:not([type="search"]) {
    background: color-mix(in srgb, var(--主题色) 25%, transparent);
    outline: none !important;
    box-shadow: 1px 1px 2px var(--阴影);
}

/* --- 弹窗 --- */
#character_popup, 
#dialogue_popup,
.draggable,        
#select_chat_popup, 
.popup:not(.transparent_dialogue_popup) { 
  border-radius: var(--圆角);
  border: none;
  box-shadow: none;
}

/* 对话弹出窗文本 */
#dialogue_popup_text {
  padding-right: 5px;
}

/* 给'提示词拆分'添加滚动条 */
.popup-content:has(#showRawPrompt) {
    overflow-y: auto;
}

/* 通知提示框 */
div.toast.toast-success {
  background: var(--SmartThemeBlurTintColor) !important;
  border-radius: var(--圆角) !important;
  color: var(--SmartThemeBodyColor) !important;
  border: 3px double var(--SmartThemeBorderColor);
  box-shadow:
    1px 1px 2px var(--辅助色-2),
    0 0 4px var(--辅助色-2) !important;
}

/* --- 预设页 --- */
/* 说明文字(如AI可见最大上下文等) */
#range_block_openai .range-block .toggle-description {
  margin-right: 0;
}

/* 滑动条名称 */
.range-block-title {
  text-align: left;
}

/* 角色名称行为 + 继续后缀 */
label[for="openai_image_inlining"] + div, 
#openai_settings .inline-drawer-header .flex-container {
  gap: 0;
  text-align: left;
}

#openai_settings .inline-drawer-header .flex-container b {
  margin-right: 3px;
}

/* --- 提示词管理器 --- */
#completion_prompt_manager {
  width: 100%; /* 调节宽度 */
}

#completion_prompt_manager_list .completion_prompt_manager_list_separator {
    display: none !important;
}

/* 提示词 & 总词符数 */
#completion_prompt_manager .completion_prompt_manager_header_advanced span {
    filter: none;
}

#completion_prompt_manager .completion_prompt_manager_header {
    color: var(--SmartThemeQuoteColor) !important;
    padding: 0;
}

.completion_prompt_manager_footer {
    padding: 0 !important;
}

#completion_prompt_manager .completion_prompt_manager_header_advanced span {
    margin-left: 0;
}

/* 条目编辑按钮 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt
span
span
span {
  filter: none !important;
}

/* 预设词条目 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
    border-radius: var(--圆角);
    border: none;
    outline: 1px solid var(--SmartThemeBorderColor);
    outline-offset: 1px;
    background: color-mix(in srgb, var(--辅助色-2) 50%, transparent);
  margin-bottom: 10px;
}

/* 未启用条目 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt_disabled {
  background: transparent;
  opacity: 0.75;
  outline: 1.8px dotted var(--SmartThemeBorderColor);
}

/* 未启用条目的字体颜色 */
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action, #completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt .completion_prompt_manager_prompt_name .fa-solid {
  color: var(--SmartThemeBodyColor);
}

/* 提示词管理器内边距 */
#completion_prompt_manager .range-block .text_pole {
    padding-left: 15px;
    padding-right: 15px;
}

/* --- 世界书 --- */
#WorldInfo {
    margin-top: 0;
}

/* 弹出窗口（iOS特定样式)  */
@supports (-webkit-touch-callout: none) {
  #world_popup {
    margin-top: 0;
    width: 100%;
  }
}

/* 世界书条目 */
.world_entry {
    margin-top: 8px;
    background: transparent;
}

/* 世界书条目卡片 */
.wi-card-entry {
  border-radius: var(--圆角);
  border: none;
  outline: none;
  background: var(--SmartThemeBlurTintColor);
}

@media screen and (max-width: 1000px) {
  .world_entry_form .inline-drawer-header  {
      border-radius: var(--圆角);
      border: none;
      outline: none;
      background: var(--辅助色-3) !important;
  }
}

/* 世界书选择器选项 */
.select2-container .select2-selection--multiple .select2-selection__choice,
.select2-container .select2-selection--single .select2-selection__choice {
    background: var(--SmartThemeBlurTintColor);
}

/* 单击展开 */
.inline-drawer.wide100p .inline-drawer-content {
    background: transparent !important;
}

/* PC端局部阴影去除 */
/* 整个选择框 */
.select2-selection.select2-selection--multiple {
  background: color-mix(in srgb, var(--SmartThemeBorderColor) 25%, var(--SmartThemeBlurTintColor));
  border: none;
  border-radius: var(--圆角);
}

/* 世界书选择器选项 */
.select2-container .select2-selection--multiple .select2-selection__choice,
.select2-container .select2-selection--single .select2-selection__choice {
  background: color-mix(in srgb, var(--辅助色) 20%, transparent);
}

/* 清除显示选项以及移除按钮背景色 */
.select2-selection__choice__remove,
.select2-selection__choice__display {
    background: transparent !important;
    line-height: 1.6;
}

/* 同时清除搜索框和显示文本 */
.select2-search__field, 
span.select2-selection.select2-selection--single {
    background: var(--SmartThemeBlurTintColor) !important;
    border-radius: var(--圆角);
}

.select2-search__field,
.select2-dropdown.select2-dropdown--below {
    box-shadow: none !important;
}

/* --- 图库 --- */
.bg_example {
    outline: none;
    box-shadow: none !important;
    border: 1px solid var(--SmartThemeBorderColor);
}

/* 图片名称 */
.BGSampleTitle {
    background: none !important;
}

.mobile-only-menu-toggle {
    border-radius: 35% !important;
}

.mobile-only-menu-toggle,
.jg-menu {
    background: var(--辅助色) !important;
    transform: scale(0.75) !important;
    opacity: 0.75;
}

/* 正则留空 by babylon */
.regex-script-container {
    padding-right: 40px;
}

/* 正则名称全显示 */
.regex_script_name {
  white-space: normal;
}
.regex-script-label.flex-container {
  align-items: center;
}

/* --- 用户管理器 --- */
#user_avatar_block .avatar-container {
  box-shadow: 1px 1px 3px var(--阴影);
}

#user_avatar_block .avatar-container.selected {
  outline: 1.5px solid var(--辅助色);  
  outline-offset: -4px;
  border: none;
  box-shadow:
      0 0 1.5px var(--辅助色),
      1px 1px 2px var(--辅助色);
}

#user_avatar_block .avatar-container.selected .ch_name {
  color: var(--辅助色);
}
#movingUIPresets {
    margin-bottom: 0 !important;
}

/* --- 角色管理器 --- */
#CharListButtonAndHotSwaps {
  margin-bottom: calc(var(--mainFontSize) * 0.85);
}

label[for="char-management-dropdown"] {
  width: 100%;
}

#avatar_div {
  flex-direction: column;
}

#avatar_controls {
  align-items: center;
}

.character_select {
  margin-top: calc(var(--mainFontSize) * 0.85);
  box-shadow: 1px 1px 3px var(--阴影);
  padding: 8px;
}

/* 星标角色卡 */
.character_select.is_fav {
  outline: 1.5px solid var(--辅助色);
  outline-offset: -4px;
  box-shadow: 1px 1px 3px var(--辅助色);
}

.character_select.is_fav .ch_name {
  color: var(--辅助色);
}

.character_select.is_fav .avatar {
  outline: none;
}

.tag.excluded::after {
  font-size: calc(var(--mainFontSize) * 2);
}

.tag.actionable {
  font-size: calc(var(--mainFontSize) * 1);
  min-height: calc(var(--mainFontSize) * 2);
  min-width: calc(var(--mainFontSize) * 2);
}

/* 角色收藏区滚动条 */
#HotSwapWrapper {
  overflow: hidden;
}

#HotSwapWrapper > div {
  overflow: auto hidden; 
  flex-wrap: nowrap;
  height: calc(var(--avatar-base-height) + 16px);
  max-height: calc(var(--avatar-base-height)* 2);
}

.avatars_inline {
  gap: 8px;
  flex-wrap: nowrap;
  overflow: visible;
}

/* ===== 5. 顶栏 & 底栏区域 ===== */
/* 去除底部菜单列表阴影 */
.list-group,
#extensionsMenu,
#options {
  box-shadow: none !important;
}

/* quickPersona */
#quickPersonaImg {
    box-shadow: none !important;
    outline: 1px solid var(--主题色) !important;
}

.list-group-item .quickPersonaMenuImg {
    box-shadow: none;
    border: 1px solid var(--主题色) !important;
    border-radius: 0 !important;
}

/* top-bar插件 */
#extensionTopBar {
  border-top: none;
  border-radius: 0 0 var(--圆角) var(--圆角) !important;
}

/* --- 顶栏 --- */
#top-bar,
body.no-blur #top-bar {
  background: var(--辅助色-2) !important;
  box-shadow: none !important;
  outline: 1px solid var(--SmartThemeBorderColor) !important;
}

/* 顶栏图标 */
.drawer-icon.fa-fw {
  display: flex;
  overflow: visible;
  justify-content: center;
  opacity: 1;
  color: var(--SmartThemeBlurTintColor);
  font-size: calc(var(--mainFontSize) * 1.15);
}

.drawer-icon.fa-fw:hover {
  color: var(--SmartThemeQuoteColor);
}

/* 底栏悬浮 by NAKARI */
#form_sheld {
  position: absolute;
  /* 底栏与屏幕底部间距 */
  bottom: 5px;
}

#chat {
  max-height: calc(100dvh + var(--bottomFormBlockSize));
  height: calc(100dvh + var(--bottomFormBlockSize));
}

/* 底栏宽度 */
#send_form {
  width: 90%;
}

#send_form, 
body.no-blur #send_form {
  border-radius: var(--圆角-中);
  background-color: var(--SmartThemeBlurTintColor) !important;
  padding: 5px 10px;
  outline: 1.5px solid var(--SmartThemeBlurTintColor) !important;
  border: 2px solid var(--主题色) !important;
  box-shadow: 0 0 0 3.5px var(--辅助色);
}

#quick-reply-rocket-button,
#send_form .fa-solid {
  color: var(--主题色-2);
  font-size: calc(var(--mainFontSize) * 1.5);
}

/* 输入框 */
#send_textarea {
  clip-path: none !important;
  border: none;
  border-radius: var(--圆角);
  background: color-mix(in srgb, var(--辅助色) 20%, transparent);
}

/* qr */
#qr--bar > .qr--buttons .qr--button {
  filter: none;
  border-radius: var(--圆角) !important;
  box-shadow: none;
